import Database from "better-sqlite3";
import path from "node:path";

/**
 * Shared, singleton SQLite connection.
 *
 * We stash the connection on `globalThis` so that Vite's dev-server module
 * reloading (HMR) doesn't spawn a second connection to the same file, which
 * would otherwise be a common source of "database is locked" errors.
 *
 * The connection itself is synchronous (better-sqlite3 executes every
 * statement synchronously on the calling thread). Combined with Node's
 * single-threaded event loop, this means that as long as a logical
 * operation (e.g. "check rate limit, then insert, then update") never
 * `await`s in the middle, no other request can interleave with it. We also
 * wrap the vote-casting logic in an explicit `db.transaction(...)` so the
 * database itself guarantees atomicity (all-or-nothing) and so that SQLite's
 * own locking/retry machinery (via `busy_timeout`) protects us from any
 * external, out-of-process writers as well.
 */

declare global {
  // eslint-disable-next-line no-var
  var __pollDb: DatabaseInstance | undefined;
}

type DatabaseInstance = InstanceType<typeof Database>;

function createConnection(): DatabaseInstance {
  const dbPath = path.resolve(process.cwd(), "poll.db");
  const db = new Database(dbPath);

  // WAL mode allows readers and writers to work concurrently without
  // blocking each other, which is important for reliability under load.
  db.pragma("journal_mode = WAL");
  // NORMAL is safe with WAL and is faster than the default FULL.
  db.pragma("synchronous = NORMAL");
  // If the DB is ever briefly busy (e.g. another process has a write lock),
  // retry for up to 5s instead of throwing SQLITE_BUSY immediately.
  db.pragma("busy_timeout = 5000");
  // Enforce the FOREIGN KEY constraints declared in the schema.
  db.pragma("foreign_keys = ON");

  return db;
}

export function getDb(): DatabaseInstance {
  if (!globalThis.__pollDb) {
    globalThis.__pollDb = createConnection();
  }
  return globalThis.__pollDb;
}

export interface PollRow {
  id: string;
  question: string;
}

export interface OptionRow {
  id: number;
  poll_id: string;
  text: string;
  votes: number;
}

export function getPoll(pollId: string): PollRow | undefined {
  return getDb()
    .prepare("SELECT id, question FROM polls WHERE id = ?")
    .get(pollId) as PollRow | undefined;
}

export function getOptions(pollId: string): OptionRow[] {
  return getDb()
    .prepare(
      "SELECT id, poll_id, text, votes FROM options WHERE poll_id = ? ORDER BY id ASC",
    )
    .all(pollId) as OptionRow[];
}

const RATE_LIMIT_MS = 5000;

export type VoteResult =
  | { ok: true; votes: Record<string, number> }
  | { ok: false; reason: "not_found" }
  | { ok: false; reason: "rate_limited" };

/**
 * Atomically validates and casts a vote.
 *
 * Everything (the poll/option existence check, the rate-limit check, the
 * insert into `votes_log`, and the increment of `options.votes`) happens
 * inside a single `better-sqlite3` transaction, so concurrent requests can
 * never observe a half-applied state, and no votes can be lost or double
 * counted.
 */
export function castVote(
  pollId: string,
  optionId: number,
  ip: string,
): VoteResult {
  const db = getDb();

  const run = db.transaction((): VoteResult => {
    const poll = db
      .prepare("SELECT id FROM polls WHERE id = ?")
      .get(pollId) as { id: string } | undefined;

    if (!poll) {
      return { ok: false, reason: "not_found" };
    }

    const option = db
      .prepare("SELECT id FROM options WHERE id = ? AND poll_id = ?")
      .get(optionId, pollId) as { id: number } | undefined;

    if (!option) {
      return { ok: false, reason: "not_found" };
    }

    const lastVote = db
      .prepare(
        "SELECT timestamp FROM votes_log WHERE poll_id = ? AND ip = ? ORDER BY timestamp DESC LIMIT 1",
      )
      .get(pollId, ip) as { timestamp: number } | undefined;

    const now = Date.now();
    if (lastVote && now - lastVote.timestamp < RATE_LIMIT_MS) {
      return { ok: false, reason: "rate_limited" };
    }

    db.prepare(
      "INSERT INTO votes_log (poll_id, ip, timestamp) VALUES (?, ?, ?)",
    ).run(pollId, ip, now);

    db.prepare("UPDATE options SET votes = votes + 1 WHERE id = ?").run(
      optionId,
    );

    const updatedOptions = db
      .prepare("SELECT id, votes FROM options WHERE poll_id = ?")
      .all(pollId) as { id: number; votes: number }[];

    const votes: Record<string, number> = {};
    for (const o of updatedOptions) {
      votes[String(o.id)] = o.votes;
    }

    return { ok: true, votes };
  });

  return run();
}

import { component$, useStore } from "@builder.io/qwik";
import { routeLoader$, type DocumentHead } from "@builder.io/qwik-city";
import { getOptions, getPoll } from "~/lib/db";

interface OptionData {
  id: number;
  text: string;
  votes: number;
}

type PollLoaderData =
  | {
      found: true;
      pollId: string;
      question: string;
      options: OptionData[];
    }
  | {
      found: false;
      pollId: string;
    };

export const usePollLoader = routeLoader$<PollLoaderData>((requestEvent) => {
  const pollId = requestEvent.params.id;
  const poll = getPoll(pollId);

  if (!poll) {
    requestEvent.status(404);
    return { found: false, pollId };
  }

  const options = getOptions(pollId).map((o) => ({
    id: o.id,
    text: o.text,
    votes: o.votes,
  }));

  return {
    found: true,
    pollId,
    question: poll.question,
    options,
  };
});

const CHART_WIDTH = 500;
const CHART_HEIGHT = 300;
const MAX_BAR_WIDTH = 400;
const CHART_LEFT = 90;
const BAR_HEIGHT = 28;
const BAR_GAP = 16;

export default component$(() => {
  const data = usePollLoader();

  const state = useStore<{ votes: Record<number, number>; error: string }>(
    {
      votes: data.value.found
        ? Object.fromEntries(data.value.options.map((o) => [o.id, o.votes]))
        : {},
      error: "",
    },
  );

  if (!data.value.found) {
    return (
      <div>
        <h1>Poll not found</h1>
        <p>No poll exists with id "{data.value.pollId}".</p>
      </div>
    );
  }

  const pollId = data.value.pollId;
  const options = data.value.options;
  const totalVotes = Object.values(state.votes).reduce(
    (sum, v) => sum + v,
    0,
  );

  return (
    <div class="poll-page">
      <h1 id="poll-question">{data.value.question}</h1>

      <svg
        id="poll-chart"
        width={CHART_WIDTH}
        height={CHART_HEIGHT}
        viewBox={`0 0 ${CHART_WIDTH} ${CHART_HEIGHT}`}
      >
        {options.map((option, i) => {
          const votes = state.votes[option.id] ?? 0;
          const total = Object.values(state.votes).reduce(
            (sum, v) => sum + v,
            0,
          );
          const width = total > 0 ? (votes / total) * MAX_BAR_WIDTH : 0;
          const y = 10 + i * (BAR_HEIGHT + BAR_GAP);

          return (
            <g key={option.id}>
              <text
                x={0}
                y={y + BAR_HEIGHT * 0.7}
                class="option-label"
                font-size="14"
              >
                {option.text}
              </text>
              <rect
                class="chart-bar"
                data-option-id={option.id}
                x={CHART_LEFT}
                y={y}
                width={width}
                height={BAR_HEIGHT}
                fill="#4f46e5"
              />
              <text
                class="vote-count"
                data-option-id={option.id}
                x={CHART_LEFT + width + 8}
                y={y + BAR_HEIGHT * 0.7}
                font-size="14"
              >
                {votes}
              </text>
            </g>
          );
        })}
      </svg>

      <p>Total votes: {totalVotes}</p>

      <div class="vote-buttons">
        {options.map((option) => (
          <button
            key={option.id}
            type="button"
            class="vote-button"
            data-option-id={option.id}
            onClick$={async () => {
              state.error = "";
              try {
                const res = await fetch(`/poll/${pollId}/vote`, {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify({ optionId: option.id }),
                });
                const body = await res.json();
                if (!res.ok) {
                  state.error =
                    (body && body.error) || "Something went wrong";
                  return;
                }
                const votes = body.votes as Record<string, number>;
                for (const key of Object.keys(votes)) {
                  state.votes[Number(key)] = votes[key];
                }
              } catch {
                state.error = "Network error, please try again.";
              }
            }}
          >
            Vote for {option.text}
          </button>
        ))}
      </div>

      {state.error && <p class="error">{state.error}</p>}
    </div>
  );
});

export const head: DocumentHead = ({ resolveValue }) => {
  const data = resolveValue(usePollLoader);
  return {
    title: data.found ? data.question : "Poll not found",
  };
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { castVote } from "~/lib/db";

/**
 * Resolves the client's IP address.
 *
 * Prefers the first entry of `X-Forwarded-For` (useful when running behind a
 * proxy/load balancer), falling back to the underlying connection's IP.
 */
function getClientIp(request: Request, connIp: string | undefined): string {
  const forwardedFor = request.headers.get("x-forwarded-for");
  if (forwardedFor) {
    const first = forwardedFor.split(",")[0]?.trim();
    if (first) {
      return first;
    }
  }
  return connIp || "unknown";
}

export const onPost: RequestHandler = async (requestEvent) => {
  const pollId = requestEvent.params.id;

  let body: unknown = null;
  try {
    body = await requestEvent.request.json();
  } catch {
    body = null;
  }

  const optionId =
    body && typeof body === "object" ? (body as Record<string, unknown>).optionId : undefined;

  if (
    typeof optionId !== "number" ||
    !Number.isInteger(optionId) ||
    !Number.isFinite(optionId)
  ) {
    requestEvent.json(400, { error: "Invalid option ID" });
    return;
  }

  const ip = getClientIp(requestEvent.request, requestEvent.clientConn.ip);

  const result = castVote(pollId, optionId, ip);

  if (!result.ok) {
    if (result.reason === "not_found") {
      requestEvent.json(404, { error: "Poll or option not found" });
      return;
    }
    // result.reason === "rate_limited"
    requestEvent.json(429, { error: "Rate limit exceeded" });
    return;
  }

  requestEvent.json(200, { success: true, votes: result.votes });
};

